#include "PagingPanel.h"
#include "StateIO.h"
#define IMGUI_DEFINE_MATH_OPERATORS
#include <imgui.h>
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <random>
#include <sstream>

namespace minios::gui {
PagingPanel::PagingPanel(){reset();}
void PagingPanel::loadExample(int i){const char*s=i==0?"7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1":i==1?"1,2,3,4,1,2,5,1,2,3,4,5":"2,3,2,1,5,2,4,5,3,2,5,2";std::snprintf(text_.data(),text_.size(),"%s",s);run();}
void PagingPanel::reset(){algorithm_=PageAlgorithm::FIFO;frames_=3;loadExample(0);status_="Loaded paging example";}
bool PagingPanel::parse(){refs_.clear();std::string s(text_.data()),token;std::replace(s.begin(),s.end(),',',' ');std::istringstream in(s);int v;while(in>>v){if(v<0){error_="Pages must be non-negative.";return false;}refs_.push_back(v);}if(refs_.empty()){error_="Enter a comma-separated reference string.";return false;}return true;}
void PagingPanel::run(){if(!parse())return;try{result_=PageReplacement::run(refs_,frames_,algorithm_);error_.clear();playback_.reset();status_=std::string("Ran ")+PageReplacement::name(algorithm_);}catch(const std::exception&e){error_=e.what();}}
void PagingPanel::exportCsv(){std::ofstream f("paging_results.csv");f<<"Step,Reference,Result,Evicted";for(int j=0;j<frames_;++j)f<<",Frame"<<j;f<<'\n';for(size_t i=0;i<result_.steps.size();++i){auto&s=result_.steps[i];f<<i<<','<<s.reference<<','<<(s.hit?"Hit":"Fault")<<','<<s.evicted;for(int p:s.frames)f<<','<<p;f<<'\n';}status_=f?"Saved paging_results.csv":"Export failed";}
std::string PagingPanel::saveState()const{std::ostringstream o;o<<"{\"references\":"<<stateio::list(refs_)<<",\"frames\":"<<frames_<<",\"algorithm\":"<<(int)algorithm_<<'}';return o.str();}
bool PagingPanel::loadState(const std::string&json){auto refs=stateio::array(json,"references");if(refs.empty())return false;refs_=refs;std::string joined;for(size_t i=0;i<refs_.size();++i){if(i)joined+=',';joined+=std::to_string(refs_[i]);}std::snprintf(text_.data(),text_.size(),"%s",joined.c_str());frames_=stateio::integer(json,"frames",3);algorithm_=(PageAlgorithm)std::clamp(stateio::integer(json,"algorithm",0),0,3);run();return error_.empty();}
void PagingPanel::render(){const char*names[]={"FIFO","LRU","Optimal","Clock"};int a=(int)algorithm_;ImGui::BeginChild("page_left",{340,0},true);ImGui::TextUnformatted("Reference string");ImGui::InputTextMultiline("##refs",text_.data(),text_.size(),{-1,75});ImGui::SetNextItemWidth(180);if(ImGui::Combo("Algorithm",&a,names,4)){algorithm_=(PageAlgorithm)a;run();}ImGui::SliderInt("Frames",&frames_,1,10);static int ex=0;const char*examples[]={"Reference check","Belady anomaly","Locality"};ImGui::SetNextItemWidth(170);if(ImGui::Combo("Example",&ex,examples,3))loadExample(ex);if(ImGui::Button("Run"))run();ImGui::SameLine();if(ImGui::Button("Randomize")){std::mt19937 g(std::random_device{}());std::string s;for(int i=0;i<20;++i){if(i)s+=',';s+=std::to_string(g()%8);}std::snprintf(text_.data(),text_.size(),"%s",s.c_str());run();}ImGui::SameLine();if(ImGui::Button("Save Results"))exportCsv();
    if(ImGui::Button("Load Belady demo")){loadExample(1);frames_=3;run();status_="Loaded Belady anomaly reference string";}if(!error_.empty())ImGui::TextColored({1,.3f,.3f,1},"%s",error_.c_str());
    ImGui::Separator();ImGui::TextUnformatted("Algorithm comparison (faults)");std::vector<std::string>labels;std::vector<float>vals;for(int i=0;i<4;++i)try{auto c=PageReplacement::run(refs_,frames_,(PageAlgorithm)i);labels.push_back(names[i]);vals.push_back((float)c.faults);}catch(...){ }barChart(labels,vals,"Faults",145);
    ImGui::TextUnformatted("Faults vs frame count");ImVec2 p=ImGui::GetCursorScreenPos(),sz(ImGui::GetContentRegionAvail().x,130);ImGui::InvisibleButton("line",sz);auto*dl=ImGui::GetWindowDrawList();dl->AddRectFilled(p,p+sz,IM_COL32(30,34,42,255),4);for(int alg=0;alg<3;++alg){ImVec2 prev;for(int f=1;f<=10;++f){auto c=PageReplacement::run(refs_,f,(PageAlgorithm)alg);ImVec2 q(p.x+12+(f-1)*(sz.x-24)/9,p.y+10+(sz.y-25)*(1-c.faults/(float)std::max<size_t>(1,refs_.size())));if(f>1)dl->AddLine(prev,q,colorFor(alg),2);dl->AddCircleFilled(q,2.5f,colorFor(alg));prev=q;}}ImGui::EndChild();ImGui::SameLine();
    ImGui::BeginChild("page_main",{0,0},true);ImGui::Text("%s with %d frames",PageReplacement::name(algorithm_),frames_);playbackControls("paging",playback_,result_.steps.size());int upto=result_.steps.empty()?-1:(int)std::min(playback_.step,result_.steps.size()-1);float cell=42;ImVec2 origin=ImGui::GetCursorScreenPos();auto*d=ImGui::GetWindowDrawList();for(int t=0;t<=upto;++t){auto&s=result_.steps[t];for(int f=0;f<frames_;++f){ImVec2 a0(origin.x+t*cell,origin.y+f*cell),b0(a0.x+cell-2,a0.y+cell-2);ImU32 col=s.hit?IM_COL32(55,145,90,255):IM_COL32(165,65,65,255);if(s.loadedFrame==f)col=IM_COL32(220,140,45,255);d->AddRectFilled(a0,b0,col,3);d->AddRect(a0,b0,IM_COL32(220,220,220,120));if(f<(int)s.frames.size()&&s.frames[f]>=0){char b[12];snprintf(b,sizeof(b),"%d",s.frames[f]);d->AddText({a0.x+14,a0.y+10},IM_COL32_WHITE,b);}}char r[12];snprintf(r,sizeof(r),"%d",s.reference);d->AddText({origin.x+t*cell+12,origin.y+frames_*cell+3},s.hit?IM_COL32(90,220,120,255):IM_COL32(240,90,90,255),r);}ImGui::Dummy({std::max(100.0f,(upto+1)*cell),frames_*cell+30});
    if(upto>=0){auto&s=result_.steps[upto];ImGui::Text("Reference %d: %s",s.reference,s.hit?"HIT":"FAULT");if(s.evicted>=0){ImGui::SameLine();ImGui::TextDisabled("evicted %d",s.evicted);}if(algorithm_==PageAlgorithm::Clock){ImVec2 c=ImGui::GetCursorScreenPos()+ImVec2(100,100);float radius=65;for(int i=0;i<frames_;++i){float angle=-1.5708f+6.28318f*i/frames_;ImVec2 q(c.x+std::cos(angle)*radius,c.y+std::sin(angle)*radius);d->AddCircleFilled(q,22,colorFor(i));char b[24];snprintf(b,sizeof(b),"%d/%d",s.frames[i],s.referenceBits[i]?1:0);d->AddText({q.x-12,q.y-8},IM_COL32_WHITE,b);}float angle=-1.5708f+6.28318f*s.clockHand/frames_;d->AddLine(c,{c.x+std::cos(angle)*(radius-25),c.y+std::sin(angle)*(radius-25)},IM_COL32(255,225,80,255),4);ImGui::Dummy({210,205});}}
    ImGui::Text("Faults %d | Hits %d | Hit ratio %.2f%% | Fault ratio %.2f%%",result_.faults,result_.hits,result_.hitRatio,result_.faultRatio);if(std::string(text_.data())=="1,2,3,4,1,2,5,1,2,3,4,5"){auto a3=PageReplacement::run(refs_,3,PageAlgorithm::FIFO),a4=PageReplacement::run(refs_,4,PageAlgorithm::FIFO);ImGui::TextColored({1,.75f,.2f,1},"Belady demo: 3 frames = %d faults, 4 frames = %d faults",a3.faults,a4.faults);}ImGui::EndChild();}
} // namespace minios::gui
